const http = require("http");
// fetch() and its classes from an npm package, against a server in the same program. Prints
// what it found; the same package under Node.js prints the same.
module.exports = async function run() {
  const server = http.createServer((req, res) => {
    let body = "";
    req.on("data", (d) => { body += d; });
    req.on("end", () => {
      if (req.url === "/redirect") {
        res.writeHead(302, { Location: "/target" });
        return res.end();
      }
      if (req.url === "/stream") {
        res.write("a".repeat(10000));
        setTimeout(() => res.end("b".repeat(10000)), 20);
        return;
      }
      if (req.url === "/slow") return setTimeout(() => res.end("late"), 500);
      if (req.url === "/status") {
        res.writeHead(404, "Nope", { "X-Thing": "1" });
        return res.end("missing");
      }
      res.setHeader("Content-Type", "application/json");
      res.setHeader("Set-Cookie", ["a=1", "b=2"]);
      res.end(JSON.stringify({ method: req.method, url: req.url, body, ct: req.headers["content-type"] ?? null, custom: req.headers["x-custom"] ?? null }));
    });
  });
  await new Promise((r) => server.listen(0, "127.0.0.1", r));
  const base = `http://127.0.0.1:${server.address().port}`;
  const r1 = await fetch(`${base}/hello`);
  console.log("get", r1.status, r1.ok, r1.statusText, r1.headers.get("content-type"), JSON.stringify(r1.headers.getSetCookie()), JSON.stringify(await r1.json()));
  const r2 = await fetch(`${base}/post`, { method: "POST", body: JSON.stringify({ x: 1 }), headers: { "Content-Type": "application/json", "X-Custom": "yes" } });
  console.log("post", JSON.stringify(await r2.json()));
  const form = new FormData();
  form.append("field", "value");
  const r3 = await fetch(`${base}/form`, { method: "PUT", body: new URLSearchParams({ a: "1", b: "two" }) });
  console.log("urlencoded", JSON.stringify(await r3.json()));
  const r4 = await fetch(`${base}/redirect`);
  console.log("redirect", r4.status, r4.redirected, r4.url.replace(base, "BASE"));
  const r5 = await fetch(`${base}/redirect`, { redirect: "manual" });
  console.log("manual", r5.status, r5.headers.get("location"));
  const r6 = await fetch(`${base}/stream`);
  let n = 0;
  for await (const chunk of r6.body) n += chunk.length;
  console.log("stream", n, r6.bodyUsed);
  const r7 = await fetch(`${base}/status`);
  console.log("status", r7.status, r7.ok, r7.statusText, r7.headers.get("x-thing"), await r7.text());
  const ac = new AbortController();
  const slow = fetch(`${base}/slow`, { signal: ac.signal });
  setTimeout(() => ac.abort(), 50);
  await slow.catch((e) => console.log("abort", e.name, e.message));
  const closed = http.createServer();
  await new Promise((r) => closed.listen(0, "127.0.0.1", r));
  const closedPort = closed.address().port;
  await new Promise((r) => closed.close(r));
  await fetch(`http://127.0.0.1:${closedPort}/`).catch((e) => console.log("refused", e.name, e.message, e.cause.code));
  const r8 = await fetch(`${base}/clone`);
  const c8 = r8.clone();
  console.log("clone", (await r8.text()).length === (await c8.text()).length);
  const d = await fetch("data:text/plain;base64,aGVsbG8=");
  console.log("data", d.headers.get("content-type"), await d.text());
  const h = new Headers({ B: "2", a: "1" });
  h.append("a", "3");
  console.log("headers", JSON.stringify([...h]), h.has("A"), h.get("a"));
  try {
    h.append("bad name", "x");
  } catch (e) {
    console.log("bad header", e.name, e.message);
  }
  const req = new Request(`${base}/x`, { method: "post", body: "hi", headers: { "x-a": "b" } });
  console.log("request", req.method, req.url.replace(base, "BASE"), req.headers.get("content-type"), await req.text(), req.bodyUsed);
  try {
    new Request(`${base}/x`, { method: "GET", body: "no" });
  } catch (e) {
    console.log("get body", e.name, e.message);
  }
  const res = new Response("text body", { status: 201, headers: { "x-y": "z" } });
  console.log("response", res.status, res.statusText, res.headers.get("content-type"), await res.text());
  console.log("json response", JSON.stringify(await Response.json({ k: [1] }).json()), Response.json({}).headers.get("content-type"));
  console.log("error response", Response.error().type, Response.error().status);
  console.log("redirect response", Response.redirect("http://x.test/", 301).headers.get("location"));
  const fd = await new Response(form).formData();
  console.log("formData", fd.get("field"));
  await new Promise((r) => server.close(r));
};
